import type { Conversation } from '@/types/mescli'
import { create } from 'zustand'
import { isDefaultTitle } from '@/utils/conversationTitle'

/**
 * 会话标题状态标记（2026-07-31 由 zustand store 收敛为模块级 Set）：
 * 这些标记只被命令式读写、无任何组件订阅其渲染，store 壳是纯负担。
 *
 * 状态推导：默认标题 → 'default'；在 autoGeneratedIds → 'auto'；其余 → 'manual'
 * （原 manuallyEditedIds 集合冗余——非默认且未标记自动生成的标题保守即视为手动）。
 */
export type ConversationTitleStateType = 'default' | 'auto' | 'manual'

const autoGeneratedIds = new Set<number>()
const autoRefreshAttemptedIds = new Set<number>()

/** 标记某会话标题已被用户手动编辑（撤销其"自动生成"归类即可，无需正向记录） */
export function markManuallyEdited(conversationId: number): void {
  autoGeneratedIds.delete(conversationId)
}

/** 标记某会话标题已被自动生成 */
export function markAutoGenerated(conversationId: number): void {
  autoGeneratedIds.add(conversationId)
}

/** 标记某会话已尝试过自动刷新标题（避免每次切换会话都刷新） */
export function markAutoRefreshAttempted(conversationId: number): void {
  autoRefreshAttemptedIds.add(conversationId)
}

/** 判断某会话是否已尝试过自动刷新标题 */
export function hasAutoRefreshAttempted(conversationId: number): boolean {
  return autoRefreshAttemptedIds.has(conversationId)
}

/** 删除会话时清理其标题状态 */
export function removeConversation(conversationId: number): void {
  autoGeneratedIds.delete(conversationId)
  autoRefreshAttemptedIds.delete(conversationId)
  useTitleRefreshStore.getState().clearRefreshing(conversationId)
}

/**
 * 标题生成进行中集合（2026-08-14 新增）——这个是**响应式**的：
 * Sidebar 会话项订阅它在标题左侧画 spinner。与上面的命令式标记刻意分开——
 * 标记没有订阅者，模块级 Set 就够；进行中状态有订阅者，才用 zustand。
 */
interface TitleRefreshState {
  refreshingIds: ReadonlySet<number>
  markRefreshing: (conversationId: number) => void
  clearRefreshing: (conversationId: number) => void
}

export const useTitleRefreshStore = create<TitleRefreshState>((set) => ({
  refreshingIds: new Set<number>(),
  markRefreshing: (conversationId) =>
    set((s) => ({ refreshingIds: new Set(s.refreshingIds).add(conversationId) })),
  clearRefreshing: (conversationId) =>
    set((s) => {
      if (!s.refreshingIds.has(conversationId)) return s
      const next = new Set(s.refreshingIds)
      next.delete(conversationId)
      return { refreshingIds: next }
    }),
}))

/** 根据当前标题判断标题状态：默认 / 自动生成 / 手动编辑 */
export function getTitleState(
  conversationId: number,
  currentTitle?: string | null
): ConversationTitleStateType {
  if (isDefaultTitle(currentTitle)) return 'default'
  if (autoGeneratedIds.has(conversationId)) return 'auto'
  // 标题非默认且未被标记自动生成，保守视为手动编辑
  return 'manual'
}

/** 从会话列表同步标题状态（清理已不存在的会话） */
export function syncFromConversations(conversations: Conversation[]): void {
  const validIds = new Set(conversations.map((c) => c.id))
  for (const ids of [autoGeneratedIds, autoRefreshAttemptedIds]) {
    for (const id of ids) {
      if (!validIds.has(id)) ids.delete(id)
    }
  }
}
